import process from 'node:process';
import { adicionar, concluir, ErroDeEntrada, listar, remover } from './dominio.js';
import { resolverArquivo } from './persistencia.js';

try {
  const comando = process.argv[2];
  const argumento = process.argv[3] ?? '';
  const caminho = resolverArquivo(process.env.TASKS_FILE, process.cwd());
  let resultado;

  switch (comando) {
    case 'list':
      resultado = await listar(caminho);
      break;
    case 'add':
      resultado = await adicionar(caminho, argumento);
      break;
    case 'done':
      resultado = await concluir(caminho, argumento);
      break;
    case 'remove':
      resultado = await remover(caminho, argumento);
      break;
    default:
      throw new ErroDeEntrada('Comando desconhecido. Use list, add, done ou remove.');
  }

  process.stdout.write(`${JSON.stringify(resultado)}\n`);
} catch (erro) {
  const mensagem = erro instanceof ErroDeEntrada
    ? erro.message
    : 'Não foi possível executar o comando. Verifique o arquivo de dados e as permissões de acesso.';
  process.stderr.write(`${mensagem}\n`);
  process.exitCode = 1;
}
import { gravarEstado, lerEstado } from './persistencia.js';

export class ErroDeEntrada extends Error {
  constructor(mensagem) {
    super(mensagem);
    this.name = 'ErroDeEntrada';
  }
}

function validarIdentificador(identificador) {
  const id = Number(identificador);
  if (
    typeof identificador !== 'string'
    || !/^\d+$/.test(identificador)
    || !Number.isSafeInteger(id)
    || id <= 0
  ) {
    throw new ErroDeEntrada('O identificador deve ser um inteiro positivo.');
  }
  return id;
}

function buscarTarefa(estado, id) {
  const tarefa = estado.tarefas.find((item) => item.id === id);
  if (!tarefa) {
    throw new ErroDeEntrada(`Não existe tarefa com o identificador ${id}.`);
  }
  return tarefa;
}

export async function listar(caminho) {
  const estado = await lerEstado(caminho);
  return estado.tarefas
    .map(({ id, title, done }) => ({ id, title, done }))
    .sort((primeira, segunda) => primeira.id - segunda.id);
}

export async function adicionar(caminho, titulo) {
  const title = titulo.trim();
  if (title.length === 0) {
    throw new ErroDeEntrada('O título da tarefa não pode ficar vazio.');
  }
  const estado = await lerEstado(caminho);
  const tarefa = { id: estado.proximoId, title, done: false };
  estado.tarefas.push(tarefa);
  estado.proximoId += 1;
  await gravarEstado(caminho, estado);
  return tarefa;
}

export async function concluir(caminho, identificador) {
  const id = validarIdentificador(identificador);
  const estado = await lerEstado(caminho);
  const tarefa = buscarTarefa(estado, id);
  if (!tarefa.done) {
    tarefa.done = true;
    await gravarEstado(caminho, estado);
  }
  return tarefa;
}

export async function remover(caminho, identificador) {
  const id = validarIdentificador(identificador);
  const estado = await lerEstado(caminho);
  buscarTarefa(estado, id);
  estado.tarefas = estado.tarefas.filter((tarefa) => tarefa.id !== id);
  await gravarEstado(caminho, estado);
  return { removed: id };
}
import { mkdir, open, readFile, rename, unlink } from 'node:fs/promises';
import { basename, dirname, join, resolve } from 'node:path';
import { pid } from 'node:process';

let sequenciaTemporaria = 0;

export function resolverArquivo(valor, diretorioAtual) {
  return resolve(diretorioAtual, valor === undefined ? './data/tasks.json' : valor);
}

export async function lerEstado(caminho) {
  let documento;
  try {
    documento = await readFile(caminho, 'utf8');
  } catch (erro) {
    if (erro.code === 'ENOENT') {
      return { proximoId: 1, tarefas: [] };
    }
    throw erro;
  }
  return JSON.parse(documento);
}

export async function gravarEstado(caminho, estado) {
  const documento = JSON.stringify({
    proximoId: estado.proximoId,
    tarefas: estado.tarefas.map(({ id, title, done }) => ({ id, title, done })),
  });
  const diretorio = dirname(caminho);
  await mkdir(diretorio, { recursive: true });
  const temporario = join(
    diretorio,
    `.${basename(caminho)}.${pid}.${Date.now()}.${++sequenciaTemporaria}.tmp`,
  );
  const arquivo = await open(temporario, 'wx');
  try {
    try {
      await arquivo.writeFile(`${documento}\n`, 'utf8');
    } finally {
      await arquivo.close();
    }
    await rename(temporario, caminho);
  } finally {
    await unlink(temporario).catch((erro) => {
      if (erro.code !== 'ENOENT') throw erro;
    });
  }
}

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { readFile, stat, writeFile } from 'node:fs/promises';
