/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { copyFile, mkdir, mkdtemp, readFile, rm, stat } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { promisify } from 'node:util';

const executar = promisify(execFile);
let copia;
try {
  copia = await mkdtemp(join(tmpdir(), 'tarefas-aceitacao-'));
  const { stdout: rastreados } = await executar('git', ['ls-files', '-z']);
  for (const arquivo of rastreados.split('\\0').filter(Boolean)) {
    const destino = join(copia, arquivo);
    await mkdir(dirname(destino), { recursive: true });
    await copyFile(arquivo, destino);
  }
  const ambiente = { ...process.env };
  delete ambiente.TASKS_FILE;
  async function iniciar(...argumentos) {
    const { stdout, stderr } = await executar('npm', ['start', ...argumentos], {
      cwd: copia, env: ambiente, timeout: 10000,
    });
    assert.equal(stderr, '');
    return JSON.parse(stdout.trim().split('\\n').at(-1));
  }
  await assert.rejects(stat(join(copia, 'node_modules')), { code: 'ENOENT' });
  assert.deepEqual(await iniciar(), []);
  await assert.rejects(stat(join(copia, 'data')), { code: 'ENOENT' });
  const tarefa = { id: 1, title: 'Validar cópia limpa', done: false };
  assert.deepEqual(await iniciar('--', 'add', tarefa.title), tarefa);
  const caminho = join(copia, 'data', 'tasks.json');
  const antes = await readFile(caminho, 'utf8');
  assert.deepEqual(await iniciar(), [tarefa]);
  assert.equal(await readFile(caminho, 'utf8'), antes);
  assert.deepEqual(await iniciar('--', 'done', '1'), { ...tarefa, done: true });
  assert.deepEqual(await iniciar(), [{ ...tarefa, done: true }]);
  assert.deepEqual(await iniciar('--', 'remove', '1'), { removed: 1 });
  assert.deepEqual(await iniciar(), []);
  assert.deepEqual(await iniciar('--', 'add', 'Preservar sequência'), {
    id: 2, title: 'Preservar sequência', done: false,
  });
  console.log('Aceitação operacional aprovada: npm start sem argumentos, criação, persistência entre processos, conclusão, remoção e sequência de identificadores numa cópia somente com arquivos rastreados, sem instalação de pacotes.');
} finally {
  if (copia) await rm(copia, { recursive: true, force: true });
}
NODE"

